    "studio.dev.sandboxQuestionVanilla": "• 为什么要采用 Standard Vanilla HTML/JS 混合？",
    "studio.dev.sandboxAnswerVanilla": "外部打包文件 (React / Vue) 通常含有极为繁冗的框架垫片，难以随卡片瞬时响应。OwnOrbit 推荐使用 AlpineJS。它仅占用极低的 CPU 周期，却能渲染出支持 LocalPersist 独立轻量缓存与多线程异步的大屏卡片。",
    "studio.dev.sandboxQuestionFramework": "• 如何把复杂的 React/Vue 项目移入？",
    "studio.dev.sandboxAnswerFramework": "将本地 React/Vue 项目执行 npm run build 打包。把生成的 dist/ 单页面内嵌 CSS 和 JS 合并输出，直接将这段 unified 静态 HTML 代码粘贴至编辑区，即可自动上架发布并激活测试运行。",
